'use client';
import {useState} from 'react';
import {destinationKey,sourceDestinations,prepareUnifiedEntries,type UnifiedSource,type UnifiedDestination,type UnifiedEntry} from '@/lib/financial-unified-entry';
import {bankCloseMoney} from '@/lib/cashier-bank-close';
type Props={source:UnifiedSource;destinations:UnifiedDestination[];disabled?:boolean;onEdited:()=>void;onPrepared:(allocations:ReturnType<typeof prepareUnifiedEntries>)=>void};
export function FinancialUnifiedEntry(props:Props){return <Entry key={[props.source.source,props.source.reservation,props.source.category,props.source.amount].join(':')} {...props}/>}
function Entry({source,destinations,disabled=false,onEdited,onPrepared}:Props){
 const [entries,setEntries]=useState<(UnifiedEntry&{key:number})[]>([{key:0,destination:'',amount:'',evidence:''}]),[nextKey,setNextKey]=useState(1),[error,setError]=useState('');
 const choices=sourceDestinations(source,destinations);
 function change(key:number,field:keyof UnifiedEntry,value:string){onEdited();setError('');setEntries(rows=>rows.map(r=>r.key===key?{...r,[field]:value}:r));}
 return <section aria-label={'Allocate source '+source.source}><h4>{source.source}</h4><p>Original balance: {bankCloseMoney(source.amount)}. Allocate the full amount to existing records or an additional balance.</p>{source.category!=='receivable'&&<p>Match deposits already recorded for this reservation to avoid importing the same balance twice.</p>}<fieldset disabled={disabled}><legend>Balance portions</legend>{entries.map((e,index)=><div key={e.key}><label className="field">Destination {index+1}<select value={e.destination} onChange={event=>change(e.key,'destination',event.target.value)}><option value="">Additional balance</option>{choices.map(d=><option key={destinationKey(d)} value={destinationKey(d)}>{d.label} · {d.kind==='invoice'?'source portion limit':'available'} {bankCloseMoney(d.available)}</option>)}</select></label><label className="field">Amount (USD) {index+1}<input inputMode="decimal" value={e.amount} onChange={event=>change(e.key,'amount',event.target.value)}/></label><label className="field">Supporting reference {index+1}<textarea maxLength={1000} value={e.evidence} onChange={event=>change(e.key,'evidence',event.target.value)}/></label>{entries.length>1&&<button type="button" onClick={()=>{onEdited();setError('');setEntries(rows=>rows.filter(r=>r.key!==e.key))}}>Remove portion {index+1}</button>}</div>)}<button type="button" disabled={entries.length>=choices.length+1} onClick={()=>{onEdited();setError('');setEntries(rows=>[...rows,{key:nextKey,destination:'',amount:'',evidence:''}]);setNextKey(k=>k+1)}}>Add portion</button><button type="button" onClick={()=>{try{onPrepared(prepareUnifiedEntries(source,entries,choices));setError('')}catch(e){setError(e instanceof Error?e.message:'Review the balance portions.')}}}>Review source allocation</button></fieldset>{error&&<p role="alert">{error}</p>}</section>;
}
